arguments.command:
$ErrorActionPreference='SilentlyContinue'
$roots = @((Get-Location).Path, (Join-Path $env:USERPROFILE 'Downloads'), (Join-Path $env:USERPROFILE 'Documents'), (Join-Path $env:USERPROFILE 'Desktop')) | Select-Object -Unique
$patterns = @('*katakis*','*denaris*')
$found = foreach ($r in $roots) {
  if (Test-Path $r) {
    Get-ChildItem -Path $r -Recurse -File -Include $patterns -ErrorAction SilentlyContinue |
      Where-Object { $_.Extension -match '^\.(d64|g64|t64|tap|prg|crt|zip|7z|rar)$|^$' } |
      Select-Object FullName, Length, LastWriteTime
  }
}
if ($found) { $found | Sort-Object LastWriteTime -Descending | Format-Table -AutoSize } else { Write-Host 'No local Katakis/Denaris C64 image found in current folder, Downloads, Documents, or Desktop.' }

